function fmt(v){
  if(v==null) return '—';
  if(Math.abs(v)>=1e6) return '€'+((v/1e6).toFixed(1))+'M';
  if(Math.abs(v)>=1e3) return '€'+((v/1e3).toFixed(0))+'K';
  return '€'+v.toFixed(0);
}
function fmtPct(v){
  if(v==null) return '—';
  return (v>=0?'+':'')+v.toFixed(2)+'%';
}

function hmColor(v){
  if(v==null||v===undefined) return '#293548';
  const c=Math.max(-6,Math.min(6,v)), n=(c+6)/12;
  let r,g,b;
  if(n<0.5){const t=n*2; r=Math.round(192+(248-192)*t); g=Math.round(57+(250-57)*t); b=Math.round(43+(252-43)*t)}
  else{const t=(n-0.5)*2; r=Math.round(248+(30-248)*t); g=Math.round(250+(132-250)*t); b=Math.round(252+(73-252)*t)}
  return `rgb(${r},${g},${b})`;
}

function kill(id){if(charts[id]){charts[id].destroy();delete charts[id]}}

// ═══════ TIME RANGE SLIDER ═══════
function onSliderInput(){
  const sf=document.getElementById('sliderFrom'), st=document.getElementById('sliderTo');
  let from=parseInt(sf.value), to=parseInt(st.value);
  if(from>to){const tmp=from;from=to;to=tmp;sf.value=from;st.value=to;}
  rangeStart=from; rangeEnd=to;
  updateSliderUI();
  render();
}
function updateSliderUI(){
  const all=getAllMonths();
  document.getElementById('sliderFromLabel').textContent=all[rangeStart]||'';
  document.getElementById('sliderToLabel').textContent=all[rangeEnd]||'';
  document.getElementById('sliderCount').textContent='('+(rangeEnd-rangeStart+1)+' meses)';
  // Update range highlight bar
  const maxIdx=getAllMonths().length-1||1;
  const pctFrom=rangeStart/maxIdx*100, pctTo=rangeEnd/maxIdx*100;
  const bar=document.getElementById('sliderRange');
  bar.style.left=pctFrom+'%'; bar.style.width=(pctTo-pctFrom)+'%';
}
function resetSlider(){
  rangeStart=0; rangeEnd=getAllMonths().length-1;
  document.getElementById('sliderFrom').value=rangeStart;
  document.getElementById('sliderTo').value=rangeEnd;
  updateSliderUI();
  render();
}

// ─── URL hash routing: #seccion/patrimonio (e.g. #resumen/ale, #evolucion/pablo) ───
const PORT_SLUG={bca:'ale',bcp:'pablo'};
const SLUG_PORT={ale:'bca',pablo:'bcp'};

function updateHash(){
  try{
    const tab=getActiveTab();
    const slug=PORT_SLUG[port]||'ale';
    const h='#'+tab+'/'+slug;
    if(location.hash!==h) history.replaceState(null,'',h);
  }catch(e){/* iframe / Lovable sandbox may block replaceState */}
}

function applyHash(){
  const h=(location.hash||'').replace('#','');
  if(!h) return;
  const parts=h.split('/');
  const tab=parts[0]||'resumen';
  const slug=parts[1]||'ale';
  // Apply portfolio
  const p=SLUG_PORT[slug];
  if(p && p!==port){
    port=p;
    document.querySelectorAll('.port-btn').forEach(b=>b.classList.toggle('active',b.dataset.port===p));
  }
  // Apply tab
  const tabEl=document.getElementById(tab);
  if(tabEl && tabEl.classList.contains('tab-content')){
    document.querySelectorAll('.tab-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
    document.querySelectorAll('.tab-content').forEach(c=>c.classList.toggle('active',c.id===tab));
    const sl=document.getElementById('timeSlider');
    if(sl) sl.style.display=(tab==='organigrama')?'none':'flex';
  }
  render();
}

function switchPort(p){
  port=p;
  document.querySelectorAll('.port-btn').forEach(b=>b.classList.toggle('active',b.dataset.port===p));
  updateHash();
  render();
}
function switchTab(t){
  document.querySelectorAll('.tab-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));
  document.querySelectorAll('.tab-content').forEach(c=>c.classList.toggle('active',c.id===t));
  const sl=document.getElementById('timeSlider');
  if(sl) sl.style.display=(t==='organigrama')?'none':'flex';
  updateHash();
  // Use rAF so Chart.js sees the visible canvas with correct dimensions
  requestAnimationFrame(()=>render());
}

function getActiveTab(){const el=document.querySelector('.tab-content.active');return el?el.id:'resumen'}

// Listen for browser back/forward navigation
try{window.addEventListener('hashchange',applyHash);}catch(e){}

/* ═══════ LIQUIDEZ (DEMO) ═══════ */
function renderLiquidez(){
  kill('liqEvoChart');kill('liqBreakdownChart');

  const d=D[port], m=d.months;
  const TARGET_PCT=1.0; // objetivo: 1% del patrimonio

  // Real data: cash from asset_alloc and total portfolio
  const aa=d.asset_alloc;
  const realCash=m.map(mi=>aa.CASH[mi]||0);
  const realTotal=m.map(mi=>{
    let t=0;['RV','RF','ALT','CASH','MULTI'].forEach(k=>{t+=(aa[k][mi]||0);});
    return t;
  });
  const realPct=m.map((_,i)=>realTotal[i]>0?((realCash[i]/realTotal[i])*100):0);
  const targetLine=m.map((_,i)=>realTotal[i]*TARGET_PCT/100);

  // Simulated: upcoming obligations next 90 days (illustrative)
  const lastCash=realCash[realCash.length-1];
  const lastTotal=realTotal[realTotal.length-1];
  const lastPct=realPct[realPct.length-1];
  const targetAbs=lastTotal*TARGET_PCT/100;

  // Mock obligations for the demo
  const obligations=[
    {desc:'Comisiones de gestión Family Office (Q1 2026)',amount:18500,days:15,type:'recurrente'},
    {desc:'Comisión depositaría (trimestral)',amount:4200,days:20,type:'recurrente'},
    {desc:'Llamada capital EQT XI (estimada)',amount:150000,days:45,type:'capital_call'},
    {desc:'Llamada capital Claret IV (estimada)',amount:75000,days:60,type:'capital_call'},
    {desc:'Llamada capital EQT Active Core Infra',amount:100000,days:80,type:'capital_call'},
    {desc:'Suscripción fondo recomendado Buyout 2026',amount:250000,days:90,type:'nueva_inversion'}
  ];
  const totalOblig=obligations.reduce((s,o)=>s+o.amount,0);
  const coverageRatio=totalOblig>0?(lastCash/totalOblig*100):999;
  const surplus=lastCash-totalOblig;

  // Simulated liquidity breakdown
  const breakdown=[
    {label:'CC EUR Goldman Sachs',value:lastCash*0.35,color:'#3b82f6'},
    {label:'CC EUR JP Morgan PB',value:lastCash*0.25,color:'#60a5fa'},
    {label:'CC EUR Andbank',value:lastCash*0.20,color:'#93c5fd'},
    {label:'CC EUR Interactive Brokers',value:lastCash*0.12,color:'#a78bfa'},
    {label:'CC USD Interactive Brokers',value:lastCash*0.08,color:'#c084fc'}
  ];

  // ─── KPIs ───
  const statusColor=lastPct>=TARGET_PCT*0.8?'#34d399':lastPct>=TARGET_PCT*0.5?'#fb923c':'#ef4444';
  const statusText=lastPct>=TARGET_PCT*0.8?'En objetivo':lastPct>=TARGET_PCT*0.5?'Por debajo':'Alerta';
  const excessAbs=lastCash-targetAbs;
  const coverColor=coverageRatio>=150?'#34d399':coverageRatio>=100?'#fb923c':'#ef4444';
  const daysRunway=lastTotal>0?Math.round(lastCash/((totalOblig/90))):0;

  let kh='';
  kh+=`<div class="kpi"><div class="kpi-label">Liquidez Actual</div><div class="kpi-value" style="color:#e2e8f0">${fmt(lastCash)}</div><div class="kpi-sub">${lastPct.toFixed(2)}% de la cartera</div></div>`;
  kh+=`<div class="kpi"><div class="kpi-label">Objetivo (${TARGET_PCT}%)</div><div class="kpi-value" style="color:#f59e0b">${fmt(targetAbs)}</div><div class="kpi-sub">${excessAbs>=0?'Exceso: +'+fmt(excessAbs):'Déficit: '+fmt(excessAbs)}</div></div>`;
  kh+=`<div class="kpi"><div class="kpi-label">Estado</div><div class="kpi-value" style="color:${statusColor}">${statusText}</div><div class="kpi-sub">${lastPct.toFixed(2)}% vs ${TARGET_PCT}% obj.</div></div>`;
  kh+=`<div class="kpi"><div class="kpi-label">Cobertura 90d</div><div class="kpi-value" style="color:${coverColor}">${coverageRatio.toFixed(0)}%</div><div class="kpi-sub">${fmt(lastCash)} / ${fmt(totalOblig)} obligaciones</div></div>`;
  kh+=`<div class="kpi"><div class="kpi-label">Cash Drag Estimado</div><div class="kpi-value neg">-${(lastPct*0.08).toFixed(0)} bps/año</div><div class="kpi-sub">Coste de oportunidad de la liquidez</div></div>`;
  kh+=`<div class="kpi"><div class="kpi-label">Runway</div><div class="kpi-value" style="color:#60a5fa">${daysRunway} días</div><div class="kpi-sub">Días de cobertura al ritmo actual</div></div>`;
  document.getElementById('liqKpis').innerHTML=kh;

  // ─── Evolution Chart ───
  const ctx1=document.getElementById('liqEvoChart').getContext('2d');
  charts.liqEvoChart=new Chart(ctx1,{
    type:'line',
    data:{
      labels:m,
      datasets:[
        {label:'Liquidez (€)',data:realCash,borderColor:'#3b82f6',backgroundColor:'#3b82f622',borderWidth:2.5,fill:true,pointRadius:0,tension:0.3,yAxisID:'y'},
        {label:'Objetivo '+TARGET_PCT+'% (€)',data:targetLine,borderColor:'#f59e0b',backgroundColor:'transparent',borderWidth:2,borderDash:[8,4],fill:false,pointRadius:0,tension:0.3,yAxisID:'y'},
        {label:'Liquidez (%)',data:realPct,borderColor:'#34d399',backgroundColor:'transparent',borderWidth:1.5,fill:false,pointRadius:3,pointBackgroundColor:realPct.map(p=>p>=TARGET_PCT?'#34d399':p>=TARGET_PCT*0.5?'#fb923c':'#ef4444'),tension:0.3,yAxisID:'y2'}
      ]
    },
    options:{
      responsive:true,maintainAspectRatio:false,
      interaction:{mode:'index',intersect:false},
      plugins:{
        legend:{position:'bottom',labels:{color:'#94a3b8',boxWidth:window.innerWidth<=480?8:12,font:{size:window.innerWidth<=480?9:11},padding:window.innerWidth<=480?6:10}},
        tooltip:{callbacks:{
          label:function(ctx){
            if(ctx.dataset.yAxisID==='y2') return ctx.dataset.label+': '+ctx.raw.toFixed(2)+'%';
            return ctx.dataset.label+': '+fmt(ctx.raw);
          }
        }},
        annotation:{ // target zone (visual only, Chart.js 3 doesn't have annotation plugin built-in, use borderDash line instead)
        }
      },
      scales:{
        x:{ticks:{color:'#64748b',font:{size:10}},grid:{color:'#1e293b'}},
        y:{position:'left',ticks:{color:'#64748b',callback:v=>fmt(v)},grid:{color:'#293548'},title:{display:true,text:'€',color:'#64748b',font:{size:10}}},
        y2:{position:'right',min:0,max:Math.max(5,Math.ceil(Math.max(...realPct)*1.5)),ticks:{color:'#34d39988',callback:v=>v.toFixed(1)+'%',font:{size:10}},grid:{display:false},title:{display:true,text:'% Cartera',color:'#34d39988',font:{size:10}}}
      }
    }
  });

  // ─── Breakdown Donut ───
  const ctx2=document.getElementById('liqBreakdownChart').getContext('2d');
  charts.liqBreakdownChart=new Chart(ctx2,{
    type:'doughnut',
    data:{
      labels:breakdown.map(b=>b.label),
      datasets:[{data:breakdown.map(b=>b.value),backgroundColor:breakdown.map(b=>b.color),borderWidth:0}]
    },
    options:{
      responsive:true,maintainAspectRatio:false,cutout:'65%',
      plugins:{
        legend:{position:'bottom',labels:{color:'#94a3b8',boxWidth:window.innerWidth<=480?7:10,font:{size:window.innerWidth<=480?8:11},padding:window.innerWidth<=480?5:8}},
        tooltip:{callbacks:{label:function(ctx){return ctx.label+': '+fmt(ctx.raw)+' ('+((ctx.raw/lastCash)*100).toFixed(1)+'%)';}}}
      }
    }
  });

  // ─── Coverage Panel (90-day obligations) ───
  let cp='<div style="display:flex;flex-direction:column;gap:8px">';

  // Progress bar showing total coverage
  const barPct=Math.min(100,(coverageRatio));
  const barColor=coverageRatio>=150?'#34d399':coverageRatio>=100?'#fb923c':'#ef4444';
  cp+=`<div style="margin-bottom:8px">`;
  cp+=`<div style="display:flex;justify-content:space-between;margin-bottom:4px"><span style="color:#94a3b8;font-size:11px">Liquidez disponible</span><span style="color:#e2e8f0;font-size:11px;font-weight:600">${fmt(lastCash)}</span></div>`;
  cp+=`<div style="position:relative;height:24px;background:#1e293b;border-radius:6px;overflow:hidden;border:1px solid #334155">`;
  cp+=`<div style="position:absolute;left:0;top:0;height:100%;width:${barPct}%;background:${barColor};border-radius:5px;transition:width .3s"></div>`;
  cp+=`<div style="position:absolute;left:0;top:0;width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.5)">${coverageRatio.toFixed(0)}% cobertura</div>`;
  cp+=`</div>`;
  cp+=`<div style="display:flex;justify-content:space-between;margin-top:4px"><span style="color:#94a3b8;font-size:10px">Obligaciones 90d: ${fmt(totalOblig)}</span><span style="color:${surplus>=0?'#34d399':'#ef4444'};font-size:10px;font-weight:600">${surplus>=0?'Superávit: +'+fmt(surplus):'Déficit: '+fmt(surplus)}</span></div>`;
  cp+=`</div>`;

  // Obligations list
  cp+='<table style="width:100%;border-collapse:collapse;font-size:11px;color:#cbd5e1">';
  cp+='<thead><tr style="border-bottom:1px solid #334155"><th style="text-align:left;padding:4px 6px;color:#64748b">Obligación</th><th style="text-align:right;padding:4px 6px;color:#64748b">Importe</th><th style="text-align:center;padding:4px 6px;color:#64748b">Días</th><th style="text-align:center;padding:4px 6px;color:#64748b">Tipo</th></tr></thead><tbody>';
  const typeColors={recurrente:'#60a5fa',capital_call:'#f59e0b',nueva_inversion:'#a78bfa'};
  const typeLabels={recurrente:'Recurrente',capital_call:'Capital Call',nueva_inversion:'Nueva Inv.'};
  let cumOblig=0;
  obligations.forEach(o=>{
    cumOblig+=o.amount;
    const covered=cumOblig<=lastCash;
    cp+=`<tr style="border-bottom:1px solid #1e293b;${!covered?'opacity:0.6':''}">`;
    cp+=`<td style="padding:4px 6px">${covered?'✅':'⚠️'} ${o.desc}</td>`;
    cp+=`<td style="text-align:right;padding:4px 6px;font-weight:600">${fmt(o.amount)}</td>`;
    cp+=`<td style="text-align:center;padding:4px 6px">${o.days}d</td>`;
    cp+=`<td style="text-align:center;padding:4px 6px"><span style="padding:2px 6px;border-radius:4px;background:${typeColors[o.type]||'#64748b'}22;color:${typeColors[o.type]||'#64748b'};font-size:10px;font-weight:600">${typeLabels[o.type]||o.type}</span></td>`;
    cp+=`</tr>`;
  });
  cp+='</tbody></table>';
  cp+='</div>';
  document.getElementById('liqCoveragePanel').innerHTML=cp;

  // ─── Actions Panel ───
  const actions=[];

  // Assess current state
  if(lastPct>TARGET_PCT*1.5){
    const excess=lastCash-targetAbs;
    actions.push({icon:'💰',title:'Exceso de Liquidez — Invertir',priority:'alta',color:'#f59e0b',
      detail:`Mantienes <strong>${lastPct.toFixed(2)}%</strong> en liquidez frente al objetivo de ${TARGET_PCT}%. El exceso de <strong style="color:#f59e0b">${fmt(excess)}</strong> genera un cash drag estimado de <strong>-${(lastPct*0.08).toFixed(0)} bps/año</strong>. Considerar invertir el exceso en el fondo monetario con mejor yield o adelantar compromisos de alternativos.`,
      metric:`-${(lastPct*0.08).toFixed(0)} bps/año`});
  } else if(lastPct<TARGET_PCT*0.5){
    actions.push({icon:'🚨',title:'Liquidez Crítica — Acción Inmediata',priority:'alta',color:'#ef4444',
      detail:`Solo <strong>${lastPct.toFixed(2)}%</strong> de liquidez frente al ${TARGET_PCT}% objetivo. Riesgo de no poder atender llamadas de capital. Recomendación: reembolsar parcialmente algún fondo monetario o solicitar línea de crédito puente.`,
      metric:lastPct.toFixed(2)+'%'});
  } else if(lastPct<TARGET_PCT){
    actions.push({icon:'⚠️',title:'Liquidez por Debajo del Objetivo',priority:'media',color:'#fb923c',
      detail:`La liquidez actual (${lastPct.toFixed(2)}%) está por debajo del ${TARGET_PCT}% objetivo. Monitorizar de cerca las próximas llamadas de capital y considerar reducir la posición en algún fondo líquido para reponer la reserva.`,
      metric:lastPct.toFixed(2)+'%'});
  } else {
    actions.push({icon:'✅',title:'Liquidez en Rango Objetivo',priority:'info',color:'#34d399',
      detail:`La posición de liquidez (${lastPct.toFixed(2)}%) está dentro del rango objetivo. Mantener la política actual y revisar mensualmente.`,
      metric:lastPct.toFixed(2)+'%'});
  }

  if(coverageRatio<100){
    actions.push({icon:'📞',title:'Cobertura Insuficiente a 90 días',priority:'alta',color:'#ef4444',
      detail:`Las obligaciones previstas para los próximos 90 días (<strong>${fmt(totalOblig)}</strong>) superan la liquidez disponible. Déficit de <strong style="color:#ef4444">${fmt(Math.abs(surplus))}</strong>. Opciones: (1) Reembolso parcial de fondo monetario, (2) Solicitar línea de crédito Lombard sobre la cartera, (3) Diferir la suscripción del nuevo fondo Buyout.`,
      metric:coverageRatio.toFixed(0)+'% cobertura'});
  }

  // Recommendation: optimal split
  actions.push({icon:'🏗️',title:'Estructura Óptima de Liquidez',priority:'info',color:'#60a5fa',
    detail:`Para un family office con programa de alternativos activo, la estructura recomendada es: <strong>40%</strong> en cuenta operativa (pagos inmediatos), <strong>35%</strong> en depósito/monetario a 1 semana (llamadas de capital), <strong>25%</strong> en monetario a 1 mes (reserva). Diversificar entre al menos 2 entidades depositarias.`,
    metric:'40/35/25%'});

  // Cash drag optimization
  actions.push({icon:'📊',title:'Optimización del Cash Drag',priority:'media',color:'#f59e0b',
    detail:`Cada 1% de liquidez extra cuesta ~8 bps/año de cash drag vs invertir en cartera. Con un yield actual de monetarios del ~3.5%, el coste neto es ~4.5 bps por cada 1% de exceso. Objetivo: mantener el mínimo necesario (${TARGET_PCT}%) y el resto en el monetario con mejor TER.`,
    metric:'~8 bps/1%'});

  const priColors={alta:'#ef444433',media:'#fb923c33',info:'#3b82f633'};
  const priBorder={alta:'#ef4444',media:'#fb923c',info:'#3b82f6'};
  const priLabels={alta:'Alta',media:'Media',info:'Info'};
  let ap='<div style="display:flex;flex-direction:column;gap:10px">';
  actions.forEach(a=>{
    const bc=priBorder[a.priority]||'#3b82f6';
    const bg=priColors[a.priority]||'#3b82f633';
    ap+=`<div style="background:${bg};border:1px solid ${bc}66;border-left:4px solid ${bc};border-radius:8px;padding:14px 16px;display:flex;align-items:flex-start;gap:12px">`;
    ap+=`<div style="font-size:22px;line-height:1;flex-shrink:0">${a.icon}</div>`;
    ap+=`<div style="flex:1"><div style="display:flex;align-items:center;gap:8px;margin-bottom:5px"><strong style="color:#e2e8f0;font-size:13px">${a.title}</strong><span style="font-size:10px;padding:2px 6px;border-radius:4px;background:${bc}33;color:${bc};font-weight:600;border:1px solid ${bc}55">${priLabels[a.priority]}</span></div><div style="color:#cbd5e1;font-size:12px;line-height:1.6">${a.detail}</div></div>`;
    ap+=`<div style="flex-shrink:0;text-align:right;min-width:80px"><div style="font-size:10px;color:#64748b;margin-bottom:2px">Indicador</div><div style="color:${a.color};font-weight:700;font-size:13px">${a.metric}</div></div>`;
    ap+=`</div>`;
  });
  ap+='</div>';
  ap+='<p style="color:#64748b;font-size:11px;margin-top:12px;font-style:italic">⚠ Los datos de obligaciones y distribución por cuenta son <strong>simulados</strong> para esta vista previa. Con datos reales, este módulo se actualizará automáticamente con los saldos de cada entidad y las llamadas de capital confirmadas por los gestores.</p>';
  document.getElementById('liqActionsPanel').innerHTML=ap;
}

