function setOrgView(v){
  orgView=v;
  ['ale','both','pab'].forEach(k=>{
    const btn=document.getElementById('orgBtn'+(k==='ale'?'Ale':k==='pab'?'Pab':'Both'));
    if(btn){btn.style.background=k===v?'#3b82f6':'#1e293b';btn.style.color=k===v?'#fff':'#94a3b8';}
  });
  renderOrganigrama();
}

/* ═══════ INTERACTIVE ORGANIGRAMA ENGINE ═══════ */
var _orgScale=1, _orgPanX=0, _orgPanY=0, _orgDrag=null, _orgPan=null, _orgNodes=[], _orgEdges=[];

function orgZoom(delta){
  _orgScale=Math.max(0.3,Math.min(2,_orgScale+delta));
  document.getElementById('orgZoomLbl').textContent=Math.round(_orgScale*100)+'%';
  _orgApplyTransform();
}
function _orgApplyTransform(){
  const c=document.getElementById('orgNodes');
  const s=document.getElementById('orgSvg');
  if(!c||!s) return;
  const t=`translate(${_orgPanX}px,${_orgPanY}px) scale(${_orgScale})`;
  c.style.transform=t; c.style.transformOrigin='0 0';
  s.style.transform=t; s.style.transformOrigin='0 0';
  _orgUpdateMinimap();
}
function orgResetLayout(){ _orgScale=1;_orgPanX=0;_orgPanY=0;document.getElementById('orgZoomLbl').textContent='100%';renderOrganigrama(); }

