    '<div class="chart-box" style="padding:0" id="cardPais"></div>'+
    '<div class="chart-box" style="padding:0" id="cardVehicle"></div>';

  buildCard('cardBanco','Banco Custodio','🏦',byBanco,TARGETS.banco,stBanco);
  buildCard('cardGestora','Gestora / Marca','🏷️',byGestora,TARGETS.gestora,stGestora);
  buildCard('cardPais','País de Depositaría','🌍',byPais,TARGETS.pais,stPais);
  buildCard('cardVehicle','Tipo de Vehículo','📦',byVehicle,null,{color:'#22d3ee',emoji:'ℹ️',text:'Informativo',bg:'rgba(34,211,238,0.05)'});

  // ── ALERTS ──
