    'IE00BDRK7J14':4200,  // iShares IG Corporate Bond Index
    'LU2377004903':350,   // M&G (Lux) European Credit Investment
    'IE0034085260':5500,  // PIMCO GIS Global IG Credit
    'LU0389811539':9500,  // Amundi Index MSCI Europe
    'IE00B04GQX83':3800,  // Vanguard U.S. IG Credit Index
    'IE00B03HD209':39000, // Vanguard Global Stock Index USD Acc
    'IE0002639775':35000, // Vanguard U.S. 500 Stock Index Fund
    'IT0005544082':null,  // Buoni Polie (direct bond, no AUM)
    'US91282CHT18':null,  // US Treasury (direct bond, no AUM)
