    aumHtml+='<td style="text-align:right;padding:5px 8px;font-weight:600">'+pct.toFixed(1)+'%</td>';
    aumHtml+='<td style="text-align:right;padding:5px 8px;color:'+bk.color+';font-weight:600">'+(f.aum!==null?f.aum.toLocaleString('es-ES'):'—')+'</td>';
    aumHtml+='<td style="text-align:center;padding:5px 8px"><span style="font-size:9px;padding:2px 6px;border-radius:8px;background:'+bk.color+'22;color:'+bk.color+'">'+bk.label.split('(')[0].trim()+'</span></td>';
    aumHtml+='<td style="text-align:center;padding:5px 8px;font-size:14px">'+status+'</td>';
