// to approximate mid-month trade timing. Non-trade months use start-of-month weights only.
// This reduces benchmark weight mismatch from ~30 days to ~15 days for trade months.
const TRADE_MONTHS_BCA=new Set(['Mar-16','Jun-16','Sep-16','Dic-16','Mar-17','Jun-17','Sep-17','Dic-17','Mar-18','Jun-18','Sep-18','Dic-18','Mar-19','Jun-19','Sep-19','Dic-19','Mar-20','Jun-20','Sep-20','Dic-20','Mar-21','Jun-21','Sep-21','Dic-21','Mar-22','Jun-22','Sep-22','Dic-22','Mar-23','Jun-23','Sep-23','Dic-23','Mar-24','Jun-24','Sep-24','Dic-24','Mar-25','Jun-25','Sep-25','Dic-25']);
