// Helper: get blended asset_alloc weights for benchmark precision
// prevMi = previous month key (start-of-month = end of prev month)
// mi = current month key (end-of-month weights, post-trade)
// If trade month → blend 50/50; otherwise → use start-of-month weights (prevMi)
function benchWeights(aa, mi, prevMi, isTradeMo){
  const keys=['RV','RF','ALT','CASH','MULTI','RF_USD','RF_EUR','GOLD','EM'];
  const w={};
  if(!prevMi){
    // First month: no previous data, use current weights
    keys.forEach(k=>{w[k]=aa[k]?aa[k][mi]||0:0;});
  } else if(isTradeMo){
    // Trade month: blend 50% start + 50% end (mid-month approximation)
    keys.forEach(k=>{
      const prev=aa[k]?aa[k][prevMi]||0:0;
      const curr=aa[k]?aa[k][mi]||0:0;
      w[k]=(prev+curr)/2;
    });
  } else {
    // No-trade month: use start-of-month weights (= end of previous month)
    keys.forEach(k=>{w[k]=aa[k]?aa[k][prevMi]||0:0;});
  }
  return w;
}

