function getDefUSDCoeff(p){
  const t=p.tipologia||'', n=(p.producto||'').toUpperCase();
  // Gold → 100% (priced in USD). PE/Alt → 50% (globally diversified)
  if(t==='ETF Materias Primas') return 1.0;  // gold ETCs
  if(t==='Vehículo Alternativo') return /gold/i.test(p.producto||'')?1.0:0.5;  // gold=100%, PE/alt=50%
  if(t==='Fondo Monetario'||t==='Cuenta Corriente') return 0.0;
  if(t==='Fondo Multiactivo') return 0.30;
  // RF USD managed portfolios → 100% (investment grade USD bonds)
  if(/USD|U\.S\.|US TREASURY/i.test(n)) return 1.00;
  return 0.0;
}
function getUSDCoeff(p){ return p.isin&&USD_COEFF[p.isin]!==undefined?USD_COEFF[p.isin]:getDefUSDCoeff(p); }

